package et.sera.nativeapp
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import org.json.JSONObject
@Composable internal fun SeraInterviewPanel(token:String,application:String){
 var rows by remember(application){mutableStateOf<List<JSONObject>>(emptyList())};var reload by remember{mutableIntStateOf(0)};var error by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};var editor by remember{mutableStateOf(false)};var date by remember{mutableStateOf("")};var time by remember{mutableStateOf("")};var venue by remember{mutableStateOf("")};var duration by remember{mutableStateOf("30")};var evaluation by remember{mutableStateOf<String?>(null)};var score by remember{mutableStateOf("3")};var feedback by remember{mutableStateOf("")};val scope=rememberCoroutineScope()
 fun act(rpc:String,p:JSONObject){if(busy)return;busy=true;scope.launch{val r=withContext(Dispatchers.IO){spaceCall(token,rpc,p)};busy=false;error=r.second;if(r.first!=null){editor=false;evaluation=null;reload++}}}
 LaunchedEffect(token,application,reload){val r=withContext(Dispatchers.IO){spaceCall(token,"sera_interviews_list",JSONObject().put("p_application",application))};rows=spaceRows(r.first);error=r.second}
 Column(verticalArrangement=Arrangement.spacedBy(10.dp)){
 Text("Interviews",style=MaterialTheme.typography.titleLarge)
 Button(onClick={editor=true},modifier=Modifier.fillMaxWidth(),enabled=!busy,shape=RoundedCornerShape(16.dp)){Text("Schedule interview")}
 if(error.isNotBlank())Text(error,color=MaterialTheme.colorScheme.error)
 rows.forEach{r->ElevatedCard(shape=RoundedCornerShape(20.dp),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){val id=r.getString("id");val status=r.optString("status");val start=r.optString("starts_at");Text(runCatching{java.time.OffsetDateTime.parse(start).atZoneSameInstant(java.time.ZoneId.of("Africa/Addis_Ababa")).format(java.time.format.DateTimeFormatter.ofPattern("EEE, d MMM · HH:mm"))}.getOrDefault(start),style=MaterialTheme.typography.titleMedium);Text(r.optString("location"));Text(r.optInt("duration_minutes").toString()+" min · "+status,color=MaterialTheme.colorScheme.primary);if(status=="pending"||status=="accepted")TextButton(onClick={act("sera_interview_status",JSONObject().put("p_interview",id).put("p_status","cancelled"))},enabled=!busy){Text("Cancel interview")};if(status=="accepted"&&runCatching{java.time.OffsetDateTime.parse(start).toInstant().isBefore(java.time.Instant.now())}.getOrDefault(false))Button(onClick={act("sera_interview_status",JSONObject().put("p_interview",id).put("p_status","completed"))},enabled=!busy){Text("Mark completed")};if(status=="completed")Button(onClick={evaluation=id;score=r.optInt("score",3).toString();feedback=r.optString("feedback").takeUnless{it=="null"}.orEmpty()}){Text("Evaluate interview")}}}}
 }
 if(editor)SeraSignatureSheet(onDismissRequest={if(!busy)editor=false}){Column(Modifier.fillMaxWidth().imePadding().padding(20.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Schedule interview",style=MaterialTheme.typography.headlineSmall);OutlinedTextField(date,{date=it.take(10)},label={Text("Date (YYYY-MM-DD)")});OutlinedTextField(time,{time=it.take(5)},label={Text("Time (HH:mm, Addis Ababa)")});OutlinedTextField(duration,{duration=it.take(3)},label={Text("Duration (minutes)")});OutlinedTextField(venue,{venue=it.take(300)},label={Text("Venue or meeting link")});if(error.isNotBlank())Text(error,color=MaterialTheme.colorScheme.error);Button(onClick={val start=runCatching{java.time.LocalDateTime.parse(date+"T"+time).atZone(java.time.ZoneId.of("Africa/Addis_Ababa")).toInstant().toString()}.getOrNull();if(start==null)error="Enter a valid date and time." else act("sera_schedule_interview",JSONObject().put("p_application",application).put("p_starts",start).put("p_duration",duration.toIntOrNull()?:0).put("p_location",venue))},enabled=!busy&&venue.trim().length>=2&&(duration.toIntOrNull()?:0) in 15..180,modifier=Modifier.fillMaxWidth()){Text("Send invitation")}}}
 evaluation?.let{id->SeraSignatureSheet(onDismissRequest={if(!busy)evaluation=null}){Column(Modifier.fillMaxWidth().imePadding().padding(20.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Private evaluation",style=MaterialTheme.typography.headlineSmall);Row(horizontalArrangement=Arrangement.spacedBy(4.dp)){(1..5).forEach{n->FilterChip(selected=score==n.toString(),onClick={score=n.toString()},label={Text(n.toString())})}};OutlinedTextField(feedback,{feedback=it.take(4000)},label={Text("Evidence-based feedback")},modifier=Modifier.fillMaxWidth(),minLines=3);if(error.isNotBlank())Text(error,color=MaterialTheme.colorScheme.error);Button(onClick={act("sera_evaluate_interview",JSONObject().put("p_interview",id).put("p_score",score.toInt()).put("p_feedback",feedback))},enabled=!busy,modifier=Modifier.fillMaxWidth()){Text("Save evaluation")}}}}
}
